insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0001','概念データモデル','概念データモデルの説明として、最も適切なものはどれか。','DM-A-17-02-01','ipa_past','出典：令和7年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問2','[{"id": 1, "body": "階層モデル、ネットワークモデル、関係モデルがある。"}, {"id": 2, "body": "業務プロセスを抽象化して表現したものである。"}, {"id": 3, "body": "集中型DBMSを導入するか、分散型DBMSを導入するかによって内容が変わる。"}, {"id": 4, "body": "対象世界の情報構造を抽象化して表現したものである。"}]'::jsonb,4,'概念データモデルは対象となる業務世界の情報構造を抽象化して表す。業務手順を表すものでも、特定DBMSの配置方式に依存するものでもない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0002','UMLの多重度','UMLを用いて表した商品と倉庫のデータモデルに関する記述のうち、適切なものはどれか。ここで、商品の倉庫間の移動はないものとする。','DM-A-17-02-02','ipa_past','出典：令和7年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問3','[{"id": 1, "body": "1種類の商品を二つの倉庫に初めて入庫すると、“在庫商品”データが2件追加される。"}, {"id": 2, "body": "2種類の商品を一つの倉庫に入庫すると、“入庫”データが1件追加される。"}, {"id": 3, "body": "格納先となる倉庫が確定していない在庫商品が存在する。"}, {"id": 4, "body": "出庫の実績がない在庫商品は存在しない。"}]'::jsonb,1,'在庫商品は一つの商品と一つの倉庫に関連する。同じ商品でも倉庫が二つなら在庫商品の組合せは二つになる。出庫側は0件も許されるため、出庫実績がない在庫商品も存在できる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0003','モデルと具体例の整合性','データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記にはUMLを用い、オブジェクト図の一部の属性の表示は省略した。','DM-A-17-02-02','ipa_past','出典：令和7年度 秋期 システム監査技術者試験 午前Ⅱ 問21','[{"id": 1, "body": "“123456：注文”が複数の商品にリンクしているのは、誤りである。"}, {"id": 2, "body": "“2ドア冷蔵庫：商品”が複数の注文にリンクしているのは、誤りである。"}, {"id": 3, "body": "“A商店：顧客”が複数の注文にリンクしているのは、誤りである。"}, {"id": 4, "body": "“ドラム式洗濯機：商品”がどの注文にもリンクしていないのは、誤りである。"}]'::jsonb,1,'図のモデルでは各注文に対応する商品は一つである。注文123456から二つの商品へリンクしている点がモデルと矛盾する。顧客や商品から複数の注文へ関連すること、未注文の商品が存在することはモデルと矛盾しない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0004','学習と推論','クラウドで学習し、エッジデバイスで推論する機械学習ベースのエッジAIにおいて、エッジデバイスで行われる推論処理として、適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問27／出典：令和7年度 春期 応用情報技術者試験 午前 問71','[{"id": 1, "body": "一定の環境の中で試行錯誤を行い、行動に報酬を与えることで学習するプロセス"}, {"id": 2, "body": "学習したモデルに従い、実際にデータの識別などを行うプロセス"}, {"id": 3, "body": "識別などを行うためのモデルを、正解のラベルを付けたデータによって作成するプロセス"}, {"id": 4, "body": "識別などを行うためのモデルを、正解のラベルを付けないデータによって作成するプロセス"}]'::jsonb,2,'推論は学習済みのモデルを用いて新しい入力に対する識別や予測を行う処理である。ほかの選択肢は学習の方法を説明している。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0005','画像認識AIの活用','スマートファクトリーで使用されるAIを用いたマシンビジョンの目的として、適切なものはどれか。','DM-A-10-02-02','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問28／出典：令和7年度 春期 応用情報技術者試験 午前 問72','[{"id": 1, "body": "クラウドに蓄積した入出荷データを用いてAIが需要を予測し、生産数を最適化する。"}, {"id": 2, "body": "作業者が装着したVRゴーグルにAIが作業状況に応じたガイドを表示することによって、作業効率を向上させる。"}, {"id": 3, "body": "設計変更内容をAIによって整理し、製造現場に正確に伝える。"}, {"id": 4, "body": "人間の目視検査をAIが代替し、検査効率を向上させる。"}]'::jsonb,4,'マシンビジョンは画像から対象の状態などを認識する用途で使われる。選択肢では、製品の外観などを対象にした目視検査の代替が対応する。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0006','生成AIと著作権','著作権法及び関連法令によれば、生成AIを利用して画像を生成する行為又はその生成物の利用が著作権侵害にあたるか否かに関して、適切な記述はどれか。','DM-A-28-01-05','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問30／出典：令和7年度 春期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "AIが既存の著作権で保護されている画像をデータセットとして学習している場合は、そのAIを利用して画像を生成すると、いかなる場合も著作権侵害になる。"}, {"id": 2, "body": "AIを利用して生成した画像が著作権で保護された既存の画像と類似しており、それを公開した場合、著作権侵害となる可能性がある。"}, {"id": 3, "body": "AIを利用して生成した画像は、AIが自動的に創作したものであるため、いかなる状況でも著作権の対象外となり、著作権侵害の懸念は生じない。"}, {"id": 4, "body": "AIを利用して生成した画像は、生成した本人の私的使用に限って、利用が認められており、商業利用を行った場合は、いかなる場合も著作権侵害となる。"}]'::jsonb,2,'公式正答はイ。既存著作物との関係によって生成物の公開が侵害となる可能性はある。ほかの選択肢の「いかなる場合も」「いかなる状況でも」という一律の説明は適切ではない。個別の権利判断や現在の法令解釈を保証する解説ではなく、原試験の選択肢を理解するための説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0007','セキュリティの基本特性','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）における真正性及び信頼性に対する定義a～dの組合せのうち、適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0008','製造時間の制約と利益','表のような製品A、Bを製造、販売する場合、考えられる利益は最大で何円になるか。ここで、機械の年間使用可能時間は延べ15,000時間とし、年間の固定費は製品A、Bに関係なく15,000,000円とする。','DM-A-09-03-02','ipa_past','出典：令和7年度 秋期 高度試験共通 午前Ⅰ 問29／出典：令和7年度 秋期 応用情報技術者試験 午前 問77','[{"id": 1, "body": "3,750,000"}, {"id": 2, "body": "7,500,000"}, {"id": 3, "body": "16,250,000"}, {"id": 4, "body": "18,750,000"}]'::jsonb,2,'Aの時間当たり限界利益は(30,000−18,000)÷8＝1,500円、Bは(25,000−10,000)÷12＝1,250円。Aを1,875個製造する場合の限界利益は22,500,000円で、固定費15,000,000円を差し引くと7,500,000円になる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0009','リスク対応','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）におけるリスク対応についての説明として、適切なものはどれか。','DM-A-24-03-02','ipa_past','出典：令和7年度 秋期 システム監査技術者試験 午前Ⅱ 問19','[{"id": 1, "body": "リスク及びその大きさが受容可能か否かを決定するために、リスク分析の結果をリスク基準と比較するプロセス"}, {"id": 2, "body": "リスクの特質を理解し、リスクレベルを決定するプロセス"}, {"id": 3, "body": "リスクの発見、認識及び記述を行うプロセス"}, {"id": 4, "body": "リスクを修正するプロセス"}]'::jsonb,4,'リスク対応はリスクを修正するプロセスに対応する。アはリスク評価、イはリスク分析、ウはリスク特定の説明。規格由来の表現は公開前の権利確認対象とする。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0010','需要予測と時系列','様々な需要予測モデルのもととなっている時系列モデルに関する記述のうち、適切なものはどれか。','DM-A-09-03-04','ipa_past','出典：令和7年度 春期 応用情報技術者試験 午前 問74','[{"id": 1, "body": "移動平均法では、平均する期間を長くするほど、短期的な需要の変化の影響を大きく受ける。"}, {"id": 2, "body": "移動平均法は、長期的な需要のトレンドを把握するのには向かないが、直近の需要の変化を把握するのに向いている。"}, {"id": 3, "body": "指数平滑法では、平滑化定数の値が0%に近いほど直前の実績値を重視し、100%に近いほど過去の実績値を重視する。"}, {"id": 4, "body": "指数平滑法は、過去の実績値よりも直近の実績値を用いるほど予測の精度が向上すると考えられる場合に有効な手法である。"}]'::jsonb,4,'単純指数平滑法では平滑化定数が大きいほど直近の実績を強く反映する。移動平均の期間を長くすると短期変動は平滑化される。原問の選択肢ではエが適切。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0011','購買データの関連性','データ分析手法の一つである、アソシエーション分析はどれか。','DM-A-09-02-10','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問63','[{"id": 1, "body": "結果となる数値（目的変数）と要因となる数値（説明変数）との関係性について、最小二乗法を用いて分析する。気温の変化が売行きにどの程度影響するかなどの事象の予測に用いることができる。"}, {"id": 2, "body": "商品を購買するときの関連性や同時性などのルールを購買データによって見いだす。データ間の統計的なパターンや、意味のある関連性を抽出する。信頼度、支持度及びリフト値によってルールを評価し、有効性を確認する。"}, {"id": 3, "body": "多数の変数の情報（観測変数）に存する共通因子を仮定して、モデル化して分析する。共通因子を見つけることによってデータの数が増加しても複雑になることを防ぎ、現象を分かりやすく捉えることができる。"}, {"id": 4, "body": "多数の変数の情報（観測変数）をできるだけ少ない指標や次元（合成変数）で要約する。データのもつ情報をできる限り損なわずに全体の傾向を可視化することができる。"}]'::jsonb,2,'アソシエーション分析では一緒に購入される商品などの関連ルールを見つける。支持度・信頼度・リフト値を用いる説明が対応する。アは回帰、ウは因子分析、エは主成分分析の説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0012','部品制約と利益最大化','製品X、Yを1台製造するのに必要な部品数は、表のとおりである。製品1台当たりの利益がX、Yともに1万円のとき、利益は最大何万円になるか。ここで、部品Aは120個、部品Bは60個まで使えるものとする。','DM-A-09-03-02','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問75','[{"id": 1, "body": "30"}, {"id": 2, "body": "40"}, {"id": 3, "body": "45"}, {"id": 4, "body": "60"}]'::jsonb,3,'Xの台数をx、Yをyとすると3x＋2y≦120、x＋2y≦60。両制約の交点はx＝30、y＝15で45万円。軸上の最大値40万円、30万円より大きく、最大値は45万円となる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0013','著作権の保護対象','著作権法において、保護の対象とな̲り̲得̲な̲い̲も̲の̲はどれか。','DM-A-28-01-03','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "インターネットで公開されたフリーソフトウェア"}, {"id": 2, "body": "ソフトウェアの操作マニュアル"}, {"id": 3, "body": "データベース"}, {"id": 4, "body": "プログラム言語や規約（プログラム言語の用法についての特別の約束）"}]'::jsonb,4,'原試験の正答はエ。プログラム言語や規約は著作権法の当該保護対象から除かれる。無料公開というだけで著作権がなくなるわけではない。また、データベースは情報の選択や体系的構成に創作性があれば保護され得る。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0014','有効顧客の共通定義','営業部は直近90日以内に購入した顧客を、サポート部は契約が有効な顧客を「有効顧客」と呼んでいる。各部門の指標を維持しながら、全社報告で時系列比較ができるようにする方法はどれか。','DM-A-08-03-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "全社報告には、報告月に集計を担当した部門の定義を使用する。", "explanation": "担当部門が変わると測定対象も変わる。"}, {"id": 2, "body": "全社報告用の指標を別に定義し、適用日と定義変更時の比較方法を記録する。", "explanation": "測定対象を統一し、変更の前後でどの数値が比較できるか確認できる。"}, {"id": 3, "body": "部門別の顧客数を合計し、両方の部門に存在する顧客を除いて全社指標とする。", "explanation": "重複排除だけでは、全社として誰を有効とするか決まらない。"}, {"id": 4, "body": "集計ツールを統一し、全社の各部門で従来どおりの抽出条件を使用する。", "explanation": "ツールの統一だけでは定義の違いが残る。"}]'::jsonb,2,'測定対象を統一し、変更の前後でどの数値が比較できるか確認できる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0015','欠損と平均年齢の推定','紙とWebでアンケートを実施した。年齢欄の未回答は紙で多く、Web回答者の年齢構成とは異なる可能性がある。全回答者の平均年齢を推定する前に行う確認はどれか。','DM-A-08-04-02','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "全体の未回答率だけを見て、少なければ一律に除外する。", "explanation": "一部の経路に欠損が偏っていても、全体の未回答率だけでは分からない。"}, {"id": 2, "body": "Web回答者の平均年齢で、紙の未回答を一律に補完する。", "explanation": "Web回答者の平均を使える根拠が与えられていない。"}, {"id": 3, "body": "回答経路ごとの欠損率と、利用できる属性の分布を比較し、除外や補完が平均に与える影響を調べる。", "explanation": "経路ごとの違いを確認してから欠損の扱いを決める。"}, {"id": 4, "body": "紙とWebについて年齢の回答者数が等しくなるよう抽出し、残ったデータの平均を取る。", "explanation": "経路間の件数をそろえても、欠損の偏りや母集団の構成は補正されない。"}]'::jsonb,3,'経路ごとの違いを確認してから欠損の扱いを決める。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0016','ビジネスメタデータ','売上データのデータカタログに登録する情報のうち、ビジネスメタデータとして最も適切なものはどれか。','DM-A-08-05-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "売上金額は返品を控除した税抜金額である、という業務上の定義"}, {"id": 2, "body": "データベース製品のパッチ番号"}, {"id": 3, "body": "列を格納する物理ファイルのパス"}, {"id": 4, "body": "前回のバックアップジョブの実行時間"}]'::jsonb,1,'ビジネスメタデータはデータの業務上の意味や定義を表す。ほかの選択肢は技術情報や運用情報であり、売上金額の業務上の意味を説明していない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0017','生成AIが引用した資料の確認','生成AIは、社内手順書の2024年版を引用して「申請は不要」と回答した。現在の手続を案内するとき、回答の根拠を確かめる方法はどれか。','DM-A-27-02-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "2024年版の文書が存在することを確認し、その回答を採用する。", "explanation": "資料の実在だけでは、その規定が現在も適用されるとは確認できない。"}, {"id": 2, "body": "別の生成AIにも同じ手順書名を提示し、結論が一致した場合に採用する。", "explanation": "AI間の一致は元資料との整合を保証しない。"}, {"id": 3, "body": "2024年版と最新版の目次を比較し、関連する章の名称が同じなら採用する。", "explanation": "章名が同じでも規定は変更され得る。"}, {"id": 4, "body": "適用対象に該当する最新版の規定を確認し、回答の結論が該当箇所に裏付けられているかを調べる。", "explanation": "適用される文書の版と、該当規定が結論を支持するかの両方を確認している。"}]'::jsonb,4,'適用される文書の版と、該当規定が結論を支持するかの両方を確認している。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0018','同意方式と記録の組合せ','販促メールの配信は、顧客が目的を確認して事前に同意した場合だけ行う。後から、どの目的にいつ同意したか、また同意が撤回されたかを確認する。配信方式と保持する記録の組合せはどれか。','DM-A-29-01-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "オプトイン方式 ／ 現在の配信可否だけを記録する。", "explanation": "事前同意方式は合っているが、現在の状態だけでは過去の目的や日時を確認できない。"}, {"id": 2, "body": "オプトイン方式 ／ 対象の目的、同意日時及び撤回履歴を記録する。", "explanation": "事前同意の方式と、同意・撤回を追跡するための記録がそろっている。"}, {"id": 3, "body": "オプトアウト方式 ／ 対象の目的、同意日時及び撤回履歴を記録する。", "explanation": "記録内容は適切だが、事前同意による配信はオプトインである。"}, {"id": 4, "body": "オプトアウト方式 ／ 現在の配信可否だけを記録する。", "explanation": "方式が異なり、必要な履歴も確認できない。"}]'::jsonb,2,'事前同意の方式と、同意・撤回を追跡するための記録がそろっている。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0019','ディープラーニングの特徴','AIにおけるディープラーニングに関する記述として、最も適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問3（句読点を統一。解説は独自作成）','[{"id": 1, "body": "あるデータから結果を求める処理を、人間の脳神経回路のように多層の処理を重ねることによって、複雑な判断をできるようにする。"}, {"id": 2, "body": "大量のデータからまだ知られていない新たな規則や仮説を発見するために、想定値から大きく外れている例外事項を取り除きながら分析を繰り返す手法である。"}, {"id": 3, "body": "多様なデータや大量のデータに対して、三段論法、統計的手法やパターン認識手法を組み合わせることによって、高度なデータ分析を行う手法である。"}, {"id": 4, "body": "知識がルールに従って表現されており、演繹手法を利用した推論によって有意な結論を導く手法である。"}]'::jsonb,1,'ディープラーニングは、多層のニューラルネットワークによってデータの特徴を学習する手法である。単に大量のデータを使うことや、ルールに基づく推論と同じ意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0020','連関図による原因の整理','分析対象としている問題に数多くの要因が関係し、それらが相互に絡み合っているとき、原因と結果、目的と手段といった関係を追求していくことによって、因果関係を明らかにし、解決の糸口をつかむための図はどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問74（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アローダイアグラム"}, {"id": 2, "body": "パレート図"}, {"id": 3, "body": "マトリックス図"}, {"id": 4, "body": "連関図"}]'::jsonb,4,'連関図は、問題に関係する要因を因果関係で結び、複雑に絡む関係を整理する。パレート図は件数などの大きい項目を把握し、マトリックス図は二つ以上の要素の対応関係を整理するために用いる。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0021','要配慮個人情報','個人情報のうち、個人情報保護法における要配慮個人情報に該当するものはどれか。','DM-A-29-01-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問80（句読点を統一。解説は独自作成）','[{"id": 1, "body": "個人情報の取得時に、本人が取扱いの配慮を申告することによって設定される情報"}, {"id": 2, "body": "個人に割り当てられた、運転免許証、クレジットカードなどの番号"}, {"id": 3, "body": "生存する個人に関する、個人を特定するために用いられる勤務先や住所などの情報"}, {"id": 4, "body": "本人の病歴、犯罪の経歴など不当な差別や不利益を生じさせるおそれのある情報"}]'::jsonb,4,'要配慮個人情報には、病歴や犯罪の経歴など、取扱いに特に配慮を要する情報が含まれる。本人が配慮を申し出た情報すべてを意味するのではない。番号や住所は個人情報になり得るが、それだけで要配慮個人情報に該当するとは限らない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0022','交差検証による汎化性能の評価','AIにおける教師あり学習での交差検証に関する記述はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問2（句読点を統一。解説は独自作成）','[{"id": 1, "body": "過学習を防ぐために、回帰モデルに複雑さを表すペナルティ項を加え、訓練データへ過剰に適合しないようにモデルを調整する。"}, {"id": 2, "body": "学習の精度を高めるために、複数の異なるアルゴリズムのモデルで学習し、学習の結果は組み合わせて評価する。"}, {"id": 3, "body": "学習モデルの汎化性能を高めるために、単一のモデルで関連する複数の課題を学習することによって、課題間に共通する要因を獲得する。"}, {"id": 4, "body": "学習モデルの汎化性能を評価するために、データを複数のグループに分割し、一部を学習に残りを評価に使い、順にグループを入れ替えて学習と評価を繰り返す。"}]'::jsonb,4,'交差検証は、データを分割し、学習用と評価用を入れ替えて性能を評価する方法である。未知のデータへの対応力である汎化性能を見積もる。ほかの選択肢は順に正則化、アンサンブル学習、マルチタスク学習の説明である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0023','オープンデータ・バイ・デザイン','官民データ活用推進基本法などに基づいて進められているオープンデータバイデザインに関して、行政機関における取組についての記述として、適切なものはどれか。','DM-A-09-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問62（句読点を統一。解説は独自作成）','[{"id": 1, "body": "行政機関が保有する個人情報を産業振興などの目的でオープン化する場合は、データ公開に先立ち、個人情報保護委員会への届出が義務化されている。"}, {"id": 2, "body": "行政機関において収集・蓄積された既存のデータが公開される場合、営利目的の利用は許されておらず、非営利の用途に限って利用が認められている。"}, {"id": 3, "body": "行政機関における情報システムの設計において、情報セキュリティを確保する観点から、公開するデータの用途を行政機関同士の相互利用に限定している。"}, {"id": 4, "body": "対象となる行政データを、二次利用や機械判読に適した形態で無償公開することを前提に、情報システムや業務プロセスの企画、整備及び運用を行っている。"}]'::jsonb,4,'オープンデータ・バイ・デザインでは、データ公開を後から付け足すのではなく、企画や設計の段階から二次利用や機械判読を考慮する。オープンデータは営利利用や行政機関以外の利用を一律に排除するものではなく、個人情報を無条件に公開する考え方でもない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0024','ECRSによる業務改善','業務改善の4原則としてのEliminate、Combine、Rearrange、Simplifyは、業務改善を実現する上での視点を示すものである。次の業務改善例のうち、Rearrangeを適用したものはどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経費精算申請業務において、決裁に不要な人を申請フローから外し、決裁までに要する時間を短縮した。"}, {"id": 2, "body": "商品配送ルートを可視化した結果、移動距離の無駄が発見された。そこで、配送順を入れ替えることで、一日に配送できる件数を向上させた。"}, {"id": 3, "body": "表計算ソフト上で各項目を手入力していたが、一つの項目を入力すれば他の関連項目が自動計算できるように関数を設定し、作業効率を向上させた。"}, {"id": 4, "body": "複数部門が集まる会議の議事録を、各部門のスタッフが、それぞれ独自に作成していた。各部門での作成をやめ、代表者1名が作成し、部門間で共有した。"}]'::jsonb,2,'Rearrangeは、作業の順序や配置を入れ替えて改善する視点である。配送順の変更が該当する。ほかの選択肢は順にEliminate（排除）、Simplify（簡素化）、Combine（結合）に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0025','ファインチューニング','生成AIのビジネス活用において、独自のデータを学習させることにより基盤モデルを自社の業務やサービスに特化したモデルへとカスタマイズすることを何と呼ぶか。','DM-A-10-03-02','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問71（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アノテーション"}, {"id": 2, "body": "クラスタリング"}, {"id": 3, "body": "ファインチューニング"}, {"id": 4, "body": "プロンプトエンジニアリング"}]'::jsonb,3,'ファインチューニングは、学習済みのモデルに追加のデータで学習を行い、用途に適合させる方法である。プロンプトエンジニアリングは入力する指示を工夫する方法であり、モデルの追加学習とは区別する。アノテーションはデータへのラベル付け、クラスタリングは類似するデータのグループ化を指す。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0026','ベイズ統計の考え方','ベイズ統計の説明として、適切なものはどれか。','DM-A-09-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経済統計に関する国際条約に基づいて、貿易実態を正確に把握し、国の経済政策や企業の経済活動の資料とすることを目的とした指標を作成する統計手法"}, {"id": 2, "body": "事前分布・事後分布といった確率に関する考え方に基づいて体系化されたものであり、機械学習、迷惑メールフィルターなどに利用されている統計理論"}, {"id": 3, "body": "収集されたデータの代表値である平均値・中央値・最頻値を求めたり、度数分布表やヒストグラムを作成したりすることによって、データの特徴を捉える統計理論"}, {"id": 4, "body": "ビッグデータの収集・分析に当たり、分析結果の検証可能性を確保し、複数の分析結果を比較可能とするために、対象をオープンデータに限定する統計手法"}]'::jsonb,2,'ベイズ統計では、事前の確率に新たな観測結果を反映し、事後の確率へ更新する。迷惑メール判定などにも利用される。代表値やヒストグラムによってデータの特徴を要約する説明は記述統計に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0027','プログラムと著作権','著作権法で保護されるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問78（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アルゴリズム"}, {"id": 2, "body": "コンパイラのプログラム"}, {"id": 3, "body": "プログラム言語"}, {"id": 4, "body": "プロトコル"}]'::jsonb,2,'プログラムは、創作性のある具体的な表現として著作物になり得る。アルゴリズムという解法そのもの、プログラム言語、規約であるプロトコルとは区別する。原試験ではコンパイラのプログラムが正答である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0028','フィルターバブル','SNSやWeb検索などに関して、イーライ・パリサーが提唱したフィルターバブルの記述として、適切なものはどれか。','DM-A-27-01-02','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問17（句読点を統一。解説は独自作成）','[{"id": 1, "body": "PCやスマートフォンなど、使用する機器の性能やソフトウェアの機能に応じて、利用者は情報へのアクセスにフィルターがかかっており、様々な格差が生じている。"}, {"id": 2, "body": "SNS、Webの一般のインターネット利用者が発信する情報が増えたことによって、Web検索の結果は非常に膨大なものとなり、個人による適切な情報収集が難しくなった。"}, {"id": 3, "body": "広告収入を目的に、事実とは異なるフィルターのかかったニュースがSNSなどを通じて発信されるようになったので、正確な情報を検索することが困難になった。"}, {"id": 4, "body": "利用者の属性・行動などに応じ、好ましいと考えられる情報がより多く表示され、利用者は実社会とは隔てられたパーソナライズされた情報空間へと包まれる。"}]'::jsonb,4,'フィルターバブルは、個人に合わせた情報の選別によって、接する情報が偏り、異なる見方に触れにくくなる現象である。機器による情報格差、情報量の増大、偽情報の発信それ自体とは区別する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0029','親和図による情報の整理','親和図の特徴はどれか。','DM-A-09-03-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問19（句読点を統一。解説は独自作成）','[{"id": 1, "body": "原因と結果を対比させた図式表現であり、不良原因の追及に用いられる。"}, {"id": 2, "body": "錯綜した問題点や、まとまっていない意見、アイディアなどを整理し、まとめるために用いられる。"}, {"id": 3, "body": "二つ以上の変数の相互関係を表すのに役立つ。"}, {"id": 4, "body": "分布の形、目標値からのばらつき状態などから、製品の品質の状態が規格値に対して満足しているものかなどを判断するために用いられる。"}]'::jsonb,2,'親和図は、集めた意見や情報を内容の近さによってグループ化して整理する。ほかの選択肢は順に特性要因図、マトリックス図、ヒストグラムの用途に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0030','AI学習と非享受目的の著作物利用','公衆への提供などが行われた他人の著作物をAIの学習データとして利用する行為に関して、著作権法に照らして適切なものはどれか。ただし、著作物の利用は、AIによる情報解析の範囲で行われ、著作物に表現された思想又は感情を享受することを目的とするものではない。また、日本国内で作成された著作物を日本国内で利用する場合であり、利用者と著作権者との間で特段の契約は存在しないものとする。','DM-A-28-01-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問22（句読点を統一。解説は独自作成）','[{"id": 1, "body": "他人の著作物から情報を抽出してAIに学習させる行為は、どのような条件においても、一切禁止されている。"}, {"id": 2, "body": "著作権者の許諾が得られた場合に限って、著作権者との合意の範囲内において、AIの学習に利用できる。"}, {"id": 3, "body": "著作権者の利益を不当に害さない場合、その必要と認められる限度において、商業利用であるか否かを問わず、著作権者の許諾なくAIの学習に利用できる。"}, {"id": 4, "body": "著作権者の利益を不当に害する場合及び商業利用の場合を除いて、著作権者の許諾なくAIの学習に利用できる。"}]'::jsonb,3,'問題文の非享受目的などの前提では、著作権法第30条の4により、必要と認められる限度で利用できる場合がある。商業利用であることだけで一律に除外されるわけではない。著作権者の利益を不当に害する場合は対象外であり、AI学習全般が無条件に自由という意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0031','職務著作と公表名義','著作権法及び関連法令によれば、職務著作の要件のうち、プログラムの著作物の場合は満たす必要がなく、プログラム以外の著作物の場合は満たす必要があるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 システム監査技術者試験 午前Ⅱ 問13（句読点を統一。解説は独自作成）','[{"id": 1, "body": "著作権が作成者に帰属するとの取決めがないこと"}, {"id": 2, "body": "法人等が自己の著作の名義の下に公表していること"}, {"id": 3, "body": "法人等の業務に従事する者が作成していること"}, {"id": 4, "body": "法人等の発意に基づいていること"}]'::jsonb,2,'職務著作では法人等の発意や職務上の作成などの要件が問題になる。プログラムの著作物については、法人等の名義で公表するという要件は課されない。プログラム以外の著作物との違いを問う問題であり、単に会社で作ったものすべてが自動的に職務著作になるという意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0032','エラープルーフによるミスの予防','ヒューマンエラーに起因する障害の低減策の一つに、エラープルーフ化がある。エラープルーフ化の五つの原理のうち、作業ミスによるエラーの発生を未然に防ぐための原理の組みはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0033','ベイジアンフィルター','迷惑メールの検知手法であるベイジアンフィルターの説明はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問20（句読点を統一。解説は独自作成）','[{"id": 1, "body": "信頼できるメール送信元を許可リストに登録しておき、許可リストにないメール送信元からの電子メールは迷惑メールと判定する。"}, {"id": 2, "body": "電子メールが正規のメールサーバから送信されていることを検証し、迷惑メールであるかどうかを判定する。"}, {"id": 3, "body": "電子メールの第三者中継を許可しているメールサーバを登録したデータベースの掲載情報を基に、迷惑メールであるかどうかを判定する。"}, {"id": 4, "body": "利用者が振り分けた迷惑メールと正規のメールから特徴を学習し、迷惑メールであるかどうかを統計的に判定する。"}]'::jsonb,4,'ベイジアンフィルターは、分類済みのメールに含まれる語句などの特徴を学習し、迷惑メールである確率を用いて判定する。送信元の許可リストや、送信元サーバの正当性の確認だけで分類する手法ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0034','リスク特定で考慮する資産の価値','JIS Q 31000:2019（リスクマネジメント－指針）において、リスク特定で考慮することが望ましいとされている事項はどれか。','DM-A-24-03-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問40（句読点を統一。解説は独自作成）','[{"id": 1, "body": "結果の性質及び大きさ"}, {"id": 2, "body": "残留リスクが許容可能かどうかの判断"}, {"id": 3, "body": "資産及び組織の資源の性質及び価値"}, {"id": 4, "body": "事象の起こりやすさ及び結果"}]'::jsonb,3,'リスク特定では、保護すべき資産や組織の資源の性質・価値を把握し、リスクを見いだす。結果の大きさや起こりやすさの検討はリスク分析、残留リスクの許容可否の判断は評価・受容の文脈と区別する。公式正答は資産及び組織の資源の性質及び価値である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0035','ディープフェイクを悪用した攻撃','ディープフェイクを悪用した攻撃に該当するものはどれか。','DM-A-27-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問39（句読点を統一。解説は独自作成）','[{"id": 1, "body": "AI技術によって加工したCEOの音声を使用して従業員に電話をかけ、指定した銀行口座に送金するよう指示した。"}, {"id": 2, "body": "企業のPCをランサムウェアに感染させ、暗号化したデータを復号するための鍵と引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 3, "body": "企業の秘密情報を含むデータを不正に取得したと誤認させる電子メールを従業員に送付し、不正に取得したデータを公開しないことと引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 4, "body": "ディープウェブにて入手した認証情報でCEOの電子メールアカウントに不正にログインして偽りの電子メールを従業員に送付し、指定した銀行口座に送金するよう指示した。"}]'::jsonb,1,'ディープフェイクは、AIによって実在の人物に似た音声や映像などを生成・加工する技術である。CEOに似せた加工音声を使う手口が該当する。ランサムウェアや認証情報の不正利用とは異なる。音声や映像だけで本人と断定せず、別の経路で確認することが重要である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0036','表の構造から取得できる情報','化粧品の製造を行っているA社では、販売代理店を通じて商品販売を行っている。今後の販売戦略に活用するために、次の三つの表を設計した。これらの表を用いるだけでは得̲る̲こ̲と̲の̲で̲き̲な̲い̲情̲報̲はどれか。','DM-A-17-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）','[{"id": 1, "body": "商品ごとの販売数量の日別差異"}, {"id": 2, "body": "性別ごとの売れ筋商品"}, {"id": 3, "body": "販売代理店ごとの購入者数の日別差異"}, {"id": 4, "body": "販売代理店ごとの売れ筋商品"}]'::jsonb,3,'商品購入の表には購入日がないため、購入者を日付ごとに数えることができない。日別販売の表には日付があるが、購入した顧客を識別する項目がない。性別ごとの集計は顧客IDで関連付けて行える。表の項目と関連から、得られる情報と不足する情報を判断する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0037','データガバナンスを確保する理由','組織においてデータガバナンスを確保することが重要である背景及び理由として、最も適切なものはどれか。','DM-A-08-03-01','ipa_sample','出典：IPA データマネジメント試験（仮称）科目A サンプル問題 問1（2026年6月公開。読点を統一。解説は独自作成）','[{"id": 1, "body": "データの活用が広がる中で、組織内のデータの品質やセキュリティを維持し、意思決定の精度向上、法令遵守などを実現することによって、組織の価値と信頼を高めるため。"}, {"id": 2, "body": "データの活用が広がる中で、組織内のデータを部門ごとに分断（サイロ化）し、保有するデータの内容を秘匿にすることによって、部門を越えたデータアクセスを統制するため。"}, {"id": 3, "body": "デジタル技術が高度化する中で、データ基盤を導入する際の評価基準及びプロセスを組織内で確立することによって、情報システム部によるITコントロールを強化するため。"}, {"id": 4, "body": "デジタル技術が高度化する中で、データを処理する人手の業務を自動化ツールに置き換えるデジタル化を推進することによって、データ処理に関わる人的コストを最適化するため。"}]'::jsonb,1,'データガバナンスは、組織全体のデータの品質やセキュリティ、法令遵守などを支え、価値ある意思決定と組織への信頼につなげるための統制である。部門間のサイロ化を進めることではない。IT基盤の評価や業務の自動化だけに目的を限定する説明も適切ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0038','データ品質を低下させる対応','AIやBIツールの処理対象となるデータは、そのデータ品質を適切に維持することが重要である。データ品質の劣化につながる望ましくない対応だけを全て挙げた組合せはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0039','ビジネスメタデータの継続的な整備','メタデータを次のa〜cの三つに分類したとき、特にa（ビジネス及び業務に関するメタデータ）の整備が組織にとって課題となることが多い。この課題を解決する方法として、最も適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0040','項目が変動するJSONデータの格納','JSON形式で表現される図1、図2のような商品データを複数のWebサービスから取得し、商品データベースとして蓄積する際のデータの格納方法に関する記述のうち、適切なものはどれか。ここで、商品データの取得元となるWebサービスは随時変更され、項目数や内容は予測できない。したがって、商品データベースの検索時に使用するキーにはあらかじめ制限を設けない。','DM-A-09-01-01','ipa_past','出典：令和5年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）','[{"id": 1, "body": "階層型データベースを使用し、項目名を上位階層とし、値を下位階層とした2階層でデータを格納する。"}, {"id": 2, "body": "グラフデータベースを使用し、商品データの項目名の集合から成るノードと値の集合から成るノードを作り、二つのノードを関係付けたグラフとしてデータを格納する。"}, {"id": 3, "body": "ドキュメントデータベースを使用し、項目構成の違いを区別せず、商品データ単位にデータを格納する。"}, {"id": 4, "body": "関係データベースを使用し、商品データの各項目名を個別の列名とした表を定義してデータを格納する。"}]'::jsonb,3,'商品をドキュメント単位で保存すれば、取得先によってフィールドが違っていても元のまとまりを保てる。新たな項目を追加するたびに全商品の表定義を更新する必要もない。',true),
  ('DMQ-0041','所属履歴の多重度','UMLを用いて表した図のデータモデルのa、bに入れる多重度はどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0050','3層スキーマの内部スキーマ','ANSI/SPARC 3層スキーマモデルにおける内部スキーマの設計に含まれるものはどれか。','DM-A-17-01-01','ipa_past','出典：令和4年度 春期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）','[{"id": 1, "body": "SQL問合せ応答時間の向上を目的としたインデックスの定義"}, {"id": 2, "body": "エンティティ間の“1対多”、“多対多”などの関連を明示するE-Rモデルの作成"}, {"id": 3, "body": "エンティティ内やエンティティ間の整合性を保つための一意性制約や参照制約の設定"}, {"id": 4, "body": "データの冗長性を排除し、更新の一貫性と効率性を保持するための正規化"}]'::jsonb,1,'内部スキーマは、データの格納やアクセスの物理的な方式を定める。インデックスは、問い合わせ時のアクセス経路を改善するために設計する。',true),
  ('DMQ-0051','第1・第2・第3正規形','第1、第2、第3正規形とリレーションの特徴a、b、cの組合せのうち、適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0062','グラフ指向データベース','NoSQLの一種である、グラフ指向DBの特徴として、適切なものはどれか。','DM-A-09-01-01','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）','[{"id": 1, "body": "データ項目の値として階層構造のデータをドキュメントとしてもつことができる。また、ドキュメントに対しインデックスを作成することもできる。"}, {"id": 2, "body": "ノード、リレーション、プロパティで構成され、ノード間をリレーションでつないで構造化する。ノード及びリレーションはプロパティをもつことができる。"}, {"id": 3, "body": "一つのキーに対して一つの値をとる形をしている。値の型は定義されていないので、様々な型の値を格納することができる。"}, {"id": 4, "body": "一つのキーに対して複数の列をとる形をしている。関係データベースとは異なり、列の型は固定されていない。"}]'::jsonb,2,'グラフ指向データベースは、人物や商品などをノード、購入や友人関係などをノード間の関係として格納する。つながりをたどる問い合わせに向く。',true),
  ('DMQ-0063','受注を記録するUMLモデル','商品の注文を記録するクラス（顧客、商品、注文、注文明細）の構造を概念データモデルで表現する。a〜dに入れるべきクラス名の組合せはどれか。ここで、顧客は何度も注文を行い、一度に一つ以上の商品を注文でき、注文明細はそれぞれ1種類の商品に対応している。また、モデルの表記にはUMLを用いる。','DM-A-17-02-02','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）','[{"id": 1, "body": "顧客　注文　注文明細　商品"}, {"id": 2, "body": "商品　注文　注文明細　顧客"}, {"id": 3, "body": "注文　注文明細　顧客　商品"}, {"id": 4, "body": "注文明細　商品　注文　顧客"}]'::jsonb,1,'一人の顧客は複数の注文を持ち、一つの注文は複数の明細を持てる。各明細は一つの商品を指し、同じ商品を複数の明細で参照できる。',true),
  ('DMQ-0064','データレイクの格納方法','データレイクの特徴はどれか。','DM-A-09-01-01','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問31（句読点を統一。解説は独自作成）','[{"id": 1, "body": "大量のデータを分析し、単なる検索だけでは分からない隠れた規則や相関関係を見つけ出す。"}, {"id": 2, "body": "データウェアハウスに格納されたデータから特定の用途に必要なデータだけを取り出し、構成する。"}, {"id": 3, "body": "データウェアハウスやデータマートからデータを取り出し、多次元分析を行う。"}, {"id": 4, "body": "必要に応じて加工するために、データを発生したままの形で格納する。"}]'::jsonb,4,'データレイクでは、さまざまな形式のデータを受け入れ、用途が決まってから必要な構造に変換できる。例えばセンサー記録と画像を受け取った形式のまま保存しておける。',true),
  ('DMQ-0065','協調フィルタリングによる推薦','レコメンデーション（お勧め商品の提案）の例のうち、協調フィルタリングを用いたものはどれか。','DM-A-09-02-10','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）','[{"id": 1, "body": "多くの顧客の購買行動の類似性を相関分析などによって求め、顧客Aに類似した顧客Bが購入している商品を顧客Aに勧める。"}, {"id": 2, "body": "カテゴリ別に売れ筋商品のランキングを自動抽出し、リアルタイムで売れ筋情報を発信する。"}, {"id": 3, "body": "顧客情報から、年齢、性別などの人口動態変数を用い、“20代男性”、“30代女性”などにセグメント化した上で、各セグメント向けの商品を提示する。"}, {"id": 4, "body": "野球のバットを購入した人に野球のボールを勧めるなど商品間の関連に着目して、関連商品を提示する。"}]'::jsonb,1,'利用者ベースの協調フィルタリングは、購買や評価の履歴が似た人の行動から、対象者がまだ利用していない商品への関心を推定する。',true),
  ('DMQ-0066','系統図法で目的と手段を整理する','系統図法の活用例はどれか。','DM-A-09-03-03','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）','[{"id": 1, "body": "解決すべき問題を端か中央に置き、関係する要因を因果関係に従って矢印でつないで周囲に並べ、問題発生に大きく影響している重要な原因を探る。"}, {"id": 2, "body": "結果とそれに影響を及ぼすと思われる要因との関連を整理し、体系化して、魚の骨のような形にまとめる。"}, {"id": 3, "body": "事実、意見、発想を小さなカードに書き込み、カード相互の親和性によってグループ化して、解決すべき問題を明確にする。"}, {"id": 4, "body": "目的を達成するための手段を導き出し、更にその手段を実施するための幾つかの手段を考えることを繰り返し、細分化していく。"}]'::jsonb,4,'系統図法では目的を起点とし、「何をすれば達成できるか」を繰り返し考えて手段を枝分かれさせる。抽象的な目標を具体的な行動に落とし込める。',true),
  ('DMQ-0067','関係演算の和集合','関係Rと関係Sに対して、関係Xを求める関係演算はどれか。','DM-A-17-02-01','ipa_past','出典：令和3年度 秋期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）','[{"id": 1, "body": "IDで結合"}, {"id": 2, "body": "差"}, {"id": 3, "body": "直積"}, {"id": 4, "body": "和"}]'::jsonb,4,'和集合はどちらか一方にでもある行を集め、全項目が一致する重複は1行にする。IDが同じでも項目Aが異なる行は両方残る。',true),
  ('DMQ-0068','受注明細と部分従属','受注入力システムによって作成される次の表に関する記述のうち、適切なものはどれか。受注番号は受注ごとに新たに発行される番号であり、項番は1回の受注で商品コード別に連番で発行される番号である。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0072', '外部キーによる連鎖削除', '図のような関係データベースの“注文”表と“注文明細”表がある。“注文”表の行を削除すると、対応する“注文明細”表の行が、自動的に削除されるようにしたい。SQL文のON DELETE句に指定する語句はどれか。ここで、図中の実線の下線は主キーを、破線の下線は外部キーを表す。', 'DM-A-17-02-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "CASCADE", "explanation": "参照先の行を削除したとき、それを参照する行も連鎖して削除する。"}, {"id": 2, "body": "INTERSECT", "explanation": "二つの問合せ結果に共通する行を取り出す集合演算である。"}, {"id": 3, "body": "RESTRICT", "explanation": "参照している行が残っている場合、参照先の削除を制限する。"}, {"id": 4, "body": "UNIQUE", "explanation": "列又は列の組の値に一意性を要求する制約である。"}]'::jsonb, 1, '外部キーにON DELETE CASCADEを指定すると、参照先の注文を削除したとき、その注文を参照する明細も削除される。', 'ipa-original/DMQ-0072.png', true),
  ('DMQ-0073', '共有ロックと専有ロック', 'RDBMSのロックに関する記述のうち、適切なものはどれか。ここで、X、Yはトランザクションとする。', 'DM-A-17-01-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "XがA表内の特定行aに対して共有ロックを獲得しているときは、YはA表内の別の特定行bに対して専有ロックを獲得することができない。", "explanation": "行aと行bは別の行なので、行aの共有ロックだけでは行bの専有ロックを妨げない。"}, {"id": 2, "body": "XがA表内の特定行aに対して共有ロックを獲得しているときは、YはA表に対して専有ロックを獲得することができない。", "explanation": "表全体に対する専有ロックは行aを含む。行aの共有ロックが保持されている間は競合する。"}, {"id": 3, "body": "XがA表に対して共有ロックを獲得しているときでも、YはA表に対して専有ロックを獲得することができる。", "explanation": "同じ表の共有ロックと専有ロックは競合する。"}, {"id": 4, "body": "XがA表に対して専有ロックを獲得しているときでも、YはA表内の特定行aに対して専有ロックを獲得することができる。", "explanation": "表全体の専有ロックには行aも含まれ、別トランザクションの専有ロックと競合する。"}]'::jsonb, 2, 'ロックの互換性は対象範囲でも決まる。表全体に対する専有ロックの範囲には、その表の各行が含まれる。', null, true),
  ('DMQ-0074', '媒体障害からのデータベース回復', 'データベースに媒体障害が発生したときのデータベースの回復法はどれか。', 'DM-A-24-01-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "障害発生時、異常終了したトランザクションをロールバックする。", "explanation": "取り消しだけでは、記憶媒体から失われたデータを復元できない。"}, {"id": 2, "body": "障害発生時点でコミットしていたがデータベースの実更新がされていないトランザクションをロールフォワードする。", "explanation": "未反映の確定処理だけを再適用すると、媒体障害前に書込み済みだった更新を復元できない。"}, {"id": 3, "body": "障害発生時点でまだコミットもアボートもしていなかった全てのトランザクションをロールバックする。", "explanation": "未確定処理を取り消す手順であり、媒体から失われた確定データは戻らない。"}, {"id": 4, "body": "バックアップコピーでデータベースを復元し、バックアップ取得以降にコミットした全てのトランザクションをロールフォワードする。", "explanation": "バックアップを基点に確定済みの変更を積み直すことで、失われた更新を復元する。"}]'::jsonb, 4, '媒体障害で失われたファイルをバックアップから復元し、バックアップ時点より後に確定した更新をログで再適用する。', null, true),
  ('DMQ-0075', 'コンバージョン率', 'インターネット広告の効果指標として用いられるコンバージョン率の説明はどれか。', 'DM-A-09-01-02', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問73（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "Webサイト上で広告が表示された回数に対して、その広告がクリックされた回数の割合を示す指標である。", "explanation": "広告表示からクリックに至った割合はクリック率である。"}, {"id": 2, "body": "Webサイト上の広告から商品購入に至った顧客の1人当たりの広告コストを示す指標である。", "explanation": "購入などの成果1件当たりに掛かった費用を示している。"}, {"id": 3, "body": "Webサイト上の広告に掛けた費用の何倍の収益をその広告から得ることができたかを示す指標である。", "explanation": "広告費を基準に収益の大きさを評価する指標を説明している。"}, {"id": 4, "body": "Webサイト上の広告をクリックして訪れた人のうち会員登録や商品購入などに至った顧客数の割合を示す指標である。", "explanation": "訪問者のうち設定した目標行動に至った人の割合を測っている。"}]'::jsonb, 4, '会員登録や購入といった目標を達成した人の割合を測るのがコンバージョン率である。この問題では広告経由の訪問者が分母となる。', null, true),
  ('DMQ-0076', 'ワークサンプリング法', 'ワークサンプリング法の説明はどれか。', 'DM-A-09-02-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問75（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "観測回数・観測時刻を設定し、実地観測によって観測された要素作業数の比率などから、統計的理論に基づいて作業時間を見積もる。", "explanation": "観測した時点の作業の割合を標本として使っている。"}, {"id": 2, "body": "作業動作を基本動作にまで分解して、基本動作の時間標準テーブルから、構成される基本動作の時間を合計して作業時間を求める。", "explanation": "基本動作の既定時間を合算する方法である。"}, {"id": 3, "body": "作業票や作業日報などから各作業の実績時間を集計し、作業ごとに平均して標準時間を求める。", "explanation": "既存の実績記録を集計して平均する方法である。"}, {"id": 4, "body": "実際の作業動作そのものをストップウォッチで数回反復測定して、作業時間を調査する。", "explanation": "動作の所要時間を直接計測している。"}]'::jsonb, 1, 'ワークサンプリングでは個々の作業を連続計測せず、複数の時点で観測した作業の出現割合から時間配分を推定する。', null, true),
  ('DMQ-0077', 'SQL GRANTによる権限付与', '表に対するSQLのGRANT文の説明として、適切なものはどれか。', 'DM-A-24-02-02', 'ipa_past', '出典：令和2年度 10月 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "パスワードを設定してデータベースへの接続を制限する。", "explanation": "パスワードによる接続時の認証を説明している。"}, {"id": 2, "body": "ビューを作成して、ビューの基となる表のアクセスできる行や列を制限する。", "explanation": "表示する行や列を絞ったビューを定義する操作を説明している。"}, {"id": 3, "body": "表のデータを暗号化して、第三者がアクセスしてもデータの内容が分からないようにする。", "explanation": "データの内容を鍵で保護する暗号化の説明である。"}, {"id": 4, "body": "表の利用者に対し、表への問合せ、更新、追加、削除などの操作権限を付与する。", "explanation": "SELECTやUPDATEなど、表に対して許可する操作を指定している。"}]'::jsonb, 4, 'GRANTは指定した利用者やロールに、指定したデータベースオブジェクトへの操作権限を付与する。', null, true),
  ('DMQ-0078', '多対多の関連を表に変換', 'UMLを用いて表した図のデータモデルから、“部品”表、“納入”表及び“メーカ”表を関係データベース上に定義するときの解釈のうち、適切なものはどれか。', 'DM-A-17-02-02', 'ipa_past', '出典：令和2年度 10月 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "同一の部品を同一のメーカから複数回納入することは許されない。", "explanation": "一つの部品と一つのメーカの組に、複数の納入の行が対応しても多重度を満たす。"}, {"id": 2, "body": "“納入”表に外部キーは必要ない。", "explanation": "納入の行がどの部品・メーカの行に対応するかを外部キーで表す。"}, {"id": 3, "body": "部品番号とメーカ番号の組みを“納入”表の候補キーの一部にできる。", "explanation": "納入番号などで同じ組の複数の納入を区別できるなら、両番号を含む組を候補キーとして設計できる。"}, {"id": 4, "body": "“メーカ”表は、外部キーとして部品番号をもつことになる。", "explanation": "部品とメーカの関連は納入を介するため、メーカ表そのものに部品番号を持たせる必要はない。"}]'::jsonb, 3, '納入の各行は部品とメーカの各1行を参照する。部品番号とメーカ番号に納入を区別できる項目を組み合わせれば、候補キーを構成できる。', 'ipa-original/DMQ-0078.png', true),
  ('DMQ-0079', '関数従属と注文明細の正規化', '関係“注文記録”の属性間に①〜⑥の関数従属性があり、それに基づいて第3正規形まで正規化を行って、“商品”、“顧客”、“注文”、“注文明細”の各関係に分解した。関係“注文明細”として、適切なものはどれか。ここで、{X、Y}は、属性XとYの組みを表し、X→Yは、XがYを関数的に決定することを表す。また、実線の下線は主キーを表す。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0082', 'データディクショナリ', '関係データベース管理システム（RDBMS）のデータディクショナリに格納されるものはどれか。', 'DM-A-08-05-01', 'ipa_past', '出典：平成30年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "OSが管理するファイルの定義情報", "explanation": "OSが管理するファイルの情報は、DBのスキーマ定義とは別である。"}, {"id": 2, "body": "スキーマの定義情報", "explanation": "表や列など、データベースの構造を記述するメタデータが格納される。"}, {"id": 3, "body": "表に格納された列データの組", "explanation": "表の列データは管理対象のデータそのものである。"}, {"id": 4, "body": "表の列に付けられたインデックスの値", "explanation": "索引の定義はメタデータだが、索引の値は検索用の実データである。"}]'::jsonb, 2, '表や列など、データベースの構造を記述するメタデータが格納される。', null, true),
  ('DMQ-0083', 'キーバリュー型データベース', 'ビッグデータの基盤技術として利用されるNoSQLに分類されるデータベースはどれか。', 'DM-A-09-01-01', 'ipa_past', '出典：平成30年度 春期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "関係データモデルをオブジェクト指向データモデルに拡張し、操作の定義や型の継承関係の定義を可能としたデータベース", "explanation": "関係モデルを拡張するオブジェクト関係データベースの説明である。"}, {"id": 2, "body": "経営者の意思決定を支援するために、ある主題に基づくデータを現在の情報とともに過去の情報も蓄積したデータベース", "explanation": "時系列の情報も蓄積して分析に使うデータウェアハウスの説明である。"}, {"id": 3, "body": "様々な形式のデータを一つのキーに対応付けて管理するキーバリュー型データベース", "explanation": "キーに対応する値を管理する方式はNoSQLの代表例である。"}, {"id": 4, "body": "データ項目の名称や形式など、データそのものの特性を表すメタ情報を管理するデータベース", "explanation": "データディクショナリなど、データの定義を管理する仕組みである。"}]'::jsonb, 3, 'キーに対応する値を管理する方式はNoSQLの代表例である。', null, true),
  ('DMQ-0084', '剰余によるハッシュ値の衝突', '自然数を除数とした剰余を返すハッシュ関数がある。値がそれぞれ571、1168、1566である三つのレコードのキー値を入力値としてこのハッシュ関数を施したところ、全てのハッシュ値が衝突した。このとき使用した除数は幾つか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "193", "explanation": "差597は193で割り切れない。"}, {"id": 2, "body": "197", "explanation": "差597は197で割り切れない。"}, {"id": 3, "body": "199", "explanation": "差597と398がともに199の倍数なので、三つのキーの余りが等しい。"}, {"id": 4, "body": "211", "explanation": "差398は211で割り切れない。"}]'::jsonb, 3, '差597と398がともに199の倍数なので、三つのキーの余りが等しい。', null, true),
  ('DMQ-0085', 'B⁺木インデックスの範囲検索', '“部品”表のメーカコード列に対し、B⁺木インデックスを作成した。これによって、“部品”表の検索の性能改善が最も期待できる操作はどれか。ここで、部品及びメーカのデータ件数は十分に多く、“部品”表に存在するメーカコード列の値の種類は十分な数があり、かつ、均一に分散しているものとする。また、“部品”表のごく少数の行には、メーカコード列にNULLが設定されている。実線の下線は主キーを、破線の下線は外部キーを表す。', 'DM-A-17-01-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "メーカコードの値が1001以外の部品を検索する。", "explanation": "除外する値が一つだけなので、多数の行が検索対象になる。"}, {"id": 2, "body": "メーカコードの値が1001でも4001でもない部品を検索する。", "explanation": "二つの値を除外しても、検索対象は広い範囲に残る。"}, {"id": 3, "body": "メーカコードの値が4001以上、4003以下の部品を検索する。", "explanation": "狭い連続範囲を索引からたどり、読み取る行を大幅に絞れる。"}, {"id": 4, "body": "メーカコードの値がNULL以外の部品を検索する。", "explanation": "NULLが少数なので、検索対象は表の大部分になる。"}]'::jsonb, 3, '狭い連続範囲を索引からたどり、読み取る行を大幅に絞れる。', 'ipa-original/DMQ-0085.png', true),
  ('DMQ-0086', 'チャットボットの用途', '顧客との接点として注目される、チャットボットの説明はどれか。', 'DM-A-10-03-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問72（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "インターネットオークションなどで、売り手と買い手の取引を安全に行うために、第三者の仲介業者が決済や商品の受渡しを行うサービスである。", "explanation": "第三者が決済や受渡しを仲介するエスクローの説明である。"}, {"id": 2, "body": "需要を予測してネットワーク設備やシステムリソースなどを計画的に調達し、需要の変動に応じて迅速にサービスを提供する考え方である。", "explanation": "需要に応じて設備や処理能力を調整する考え方である。"}, {"id": 3, "body": "商品提案から販売、アフターサービスまでの、企業と顧客との双方向の対話を、AIを活用した自動応答機能などによって実現するシステムである。", "explanation": "チャットボットは会話の形式で顧客の問いに自動応答できる。"}, {"id": 4, "body": "スマートフォンのカメラなどを通して、利用者の視界に有用な情報を重ね合わせ、現実世界での行動や認知を支援する技術である。", "explanation": "現実の視界に情報を重ねる拡張現実の説明である。"}]'::jsonb, 3, 'チャットボットは会話の形式で顧客の問いに自動応答できる。', null, true),
  ('DMQ-0087', '意味を連想できるコード', 'コードの値からデータの対象物が連想できるものはどれか。', 'DM-A-09-02-01', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問24（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "シーケンスコード", "explanation": "連番で割り当てる方式で、連番自体は対象を表さない。"}, {"id": 2, "body": "デシマルコード", "explanation": "十進数字で分類階層を表す方式である。"}, {"id": 3, "body": "ニモニックコード", "explanation": "名称の略記など、対象を連想しやすい値を割り当てる。"}, {"id": 4, "body": "ブロックコード", "explanation": "分類ごとに番号の範囲を割り当てる方式である。"}]'::jsonb, 3, '名称の略記など、対象を連想しやすい値を割り当てる。', null, true),
  ('DMQ-0088', '物理的な格納と内部スキーマ', 'データベースを記録媒体にどのように格納するかを記述したものはどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "概念スキーマ", "explanation": "データベース全体の論理的な構造を表す。"}, {"id": 2, "body": "外部スキーマ", "explanation": "特定の利用者やアプリケーションから見た論理的な構造を表す。"}, {"id": 3, "body": "サブスキーマ", "explanation": "データベースのうち特定の利用者などが使用する部分の構造を表す。"}, {"id": 4, "body": "内部スキーマ", "explanation": "記録媒体上でのデータの物理的な格納方式を表す。"}]'::jsonb, 4, '記録媒体上でのデータの物理的な格納方式を表す。', null, true),
  ('DMQ-0089', '年度別の集計とHAVING', '過去3年分の記録を保存している“試験結果”表から、2018年度の平均点数が600点以上となったクラスのクラス名と平均点数の一覧を取得するSQL文はどれか。ここで、実線の下線は主キーを表す。
